// Des: Command run: pick a job, run it through the session, print the report, map to exit code
// Flo: open store + browser > build Sess with the ladder mode > dispatch job > print text or JSON > exit code 0-4
// I/O: Ctx + job words (caller) > Report on stdout; alert on halt; exit code
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const sess = @import("ru-sess-ctxz.zig"); const rd = @import("ru-chat-read.zig"); const snd = @import("ru-chat-send.zig"); const grp = @import("ru-chat-grou.zig"); const rem = @import("ru-chat-remi.zig"); const rec = @import("ru-reci-main.zig"); const code = @import("ct-exit-code.zig"); const snap = @import("ru-page-snap.zig");
pub const Out = struct { ok: bool, job: []const u8, mode: []const u8, sent: u32, prev: u32, skip: u32, lines: []const []const u8 };
fn join(ctx: *ctxz.Ctx, words: []const []const u8) ![]const u8 { return std.mem.join(ctx.allo, " ", words); }
fn one(done: bool) rec.Report { return if (done) .{ .sent = 1 } else .{ .prev = 1 }; }
fn canary(ses: *sess.Sess) !rec.Report { var rep: rec.Report = .{}; var lines: std.ArrayList([]const u8) = .empty; const lst = try ses.nodes(); const chats = try snap.findAll(ses.aren, lst, ses.cfg.labl_chat_role, ""); const chk = [_]struct { nam: []const u8, okz: bool }{ .{ .nam = "search box", .okz = snap.findNode(lst, "textbox", ses.cfg.labl_sear_boxz) != null }, .{ .nam = "chat list", .okz = chats.len > 0 } }; for (chk) |itm| { if (itm.okz) { rep.prev += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "ok: {s}", .{itm.nam})); } else { rep.skip += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "MISSING: {s}", .{itm.nam})); } } rep.lines = lines.items; return rep; }
fn readJob(ses: *sess.Sess) !rec.Report { const sum = try rd.readUnread(ses); var lines: std.ArrayList([]const u8) = .empty; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "read {d} chats, {d} new messages", .{ sum.chats, sum.newm })); return .{ .prev = sum.chats, .lines = lines.items }; }
fn dispatch(ctx: *ctxz.Ctx, ses: *sess.Sess, job: []const u8, arg: []const []const u8) !rec.Report { if (std.mem.eql(u8, job, "read")) return readJob(ses); if (std.mem.eql(u8, job, "reply")) return rec.run(ses, .price); if (std.mem.eql(u8, job, "summ")) return rec.run(ses, .summ); if (std.mem.eql(u8, job, "canary")) return canary(ses); if (std.mem.eql(u8, job, "say")) { if (arg.len == 0) return error.BadJob; return rec.run(ses, try rec.parse(try join(ctx, arg))); } if (std.mem.eql(u8, job, "send")) { if (arg.len < 2) return error.BadJob; return rec.run(ses, .{ .send = .{ .chat = arg[0], .text = try join(ctx, arg[1..]) } }); } if (std.mem.eql(u8, job, "remind")) { if (arg.len < 3) return error.BadJob; return rec.run(ses, .{ .remind = .{ .chat = arg[0], .whenz = arg[1], .titl = try join(ctx, arg[2..]) } }); } if (std.mem.eql(u8, job, "pin") or std.mem.eql(u8, job, "mute")) { if (arg.len < 1) return error.BadJob; return one(try grp.chatAct(ses, if (job[0] == 'p') .pin else .mute, arg[0], "")); } if (std.mem.eql(u8, job, "group")) { return one(try grp.chatAct(ses, .grop, "", if (arg.len > 0) try join(ctx, arg) else "")); } if (std.mem.eql(u8, job, "forward")) { if (arg.len < 2) return error.BadJob; return one(try grp.chatAct(ses, .forw, arg[0], arg[1])); } return error.BadJob; }
pub fn runRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.rest.len == 0) return error.BadJob; const job = ctx.args.rest[0]; var sto = try ctxz.openStor(ctx); defer sto.close(); var live = try ctxz.openLive(ctx, false); defer live.close(); var ses = sess.Sess.init(ctx.init.gpa, ctx.iozz, ctx.allo, ctx.cfg, &sto, live.conn, ctx.args.mode); ses.job = job;
const rep = dispatch(ctx, &ses, job, ctx.args.rest[1..]) catch |err| { if (err == error.Halted or err == error.NeedLogin) ctxz.alert(ctx, @errorName(err)); return err; };
const modz = @tagName(ctx.args.mode); if (ctx.args.json) { try ctxz.emit(ctx, try std.json.Stringify.valueAlloc(ctx.allo, Out{ .ok = true, .job = job, .mode = modz, .sent = rep.sent, .prev = rep.prev, .skip = rep.skip, .lines = rep.lines }, .{})); try ctxz.emit(ctx, "\n"); } else { for (rep.lines) |ln| try ctxz.emitf(ctx, "{s}\n", .{ln}); try ctxz.emitf(ctx, "{s} · mode {s} · done {d} · preview {d} · skipped {d}\n", .{ job, modz, rep.sent, rep.prev, rep.skip }); if (ctx.args.mode == .dry or ctx.args.mode == .read) try ctxz.emit(ctx, "nothing was changed (add --live to act)\n"); }
return code.jobCode(rep.sent + rep.prev, 0, rep.skip, 0, false); }
